  import java.sql.Connection;
  import java.sql.SQLException;
  import java.sql.PreparedStatement;
  import java.util.List;
  import sailpoint.connector.JDBCConnector;
  import sailpoint.object.Application;
  import sailpoint.object.ProvisioningPlan;
  import sailpoint.object.ProvisioningPlan.AccountRequest;
  import sailpoint.object.ProvisioningPlan.AttributeRequest;
  import sailpoint.object.ProvisioningResult;
	import org.apache.log4j.Logger;

  Logger custLog = Logger.getLogger("sky.claimsApp.JDBCOperationRule");
  //Connection connection = context.getJdbcConnection();
  try{

     String kid="A2195"; // (String) request.getNativeIdentity(); 
     String sql="ALTER accounts SET acc_active=? WHERE kid=?";
     PreparedStatement statemant=connection.prepareStatement(sql);
        statemant.setString (1,"true");
        statemant.setString (2,kid);
     statemant.executeUpdate();

    result.setStatus( ProvisioningResult.STATUS_COMMITTED );
  custLog.debug("Account Enable provisioning request trigger for account: "+kid);
  }
  catch( SQLException e ) 
        { 

          result.setStatus( ProvisioningResult.STATUS_FAILED );
          result.addError( e );
    			custLog.debug("Error in account enable provisioning request for account: "+kid);
    	  }

return result;
